import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1787084764000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>This page is the prose version of <a href="https://github.com/ni-c/mealie-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust model”">​</a></h2><p>A Mealie API token acts as exactly one Mealie user and inherits that user&#39;s group, household and permission flags. Whoever holds it can read and rewrite that user&#39;s whole recipe collection, meal plans, shopping lists and cookbooks, and — through <code>create_share_token</code> — publish any recipe at a URL that needs no login.</p><p>Give the server a <strong>dedicated, non-admin user</strong>. Mealie&#39;s admin-only surface (backups, restore, user management, group settings, AI provider configuration) is not exposed by any tool here, but a token minted from an admin account still carries those rights if anything else ever reaches the API with it. <code>MEALIE_READ_ONLY=true</code> narrows the server further: the write and import tools are not registered at all.</p><p>Treat every environment variable this server reads as a secret. The MCP client process, and therefore the model driving it, sees every tool result — do not point this server at an instance whose data you would not put in a model&#39;s context.</p><h2 id="not-exposed-on-purpose" tabindex="-1">Not exposed, on purpose <a class="header-anchor" href="#not-exposed-on-purpose" aria-label="Permalink to “Not exposed, on purpose”">​</a></h2><p>Everything under <code>/api/admin</code> (backups, restore, maintenance, user, group and household management, email, AI provider settings), <code>/api/users/api-tokens</code> (a tool that mints API credentials is privilege-escalation surface), the authentication routes, user CRUD and passwords, webhooks, event notifications and recipe actions (all three trigger outbound HTTP from the instance), meal plan rules, migrations, seeders, invitations, bulk export and ZIP download, and asset and image uploads.</p><p><code>PUT /api/recipes/{slug}</code> is not exposed either: it replaces the entire 33-field recipe object, so a partial update through it silently drops ingredients, steps and tags. <code>update_recipe</code> uses <code>PATCH</code>.</p><h2 id="confirmation-tokens" tabindex="-1">Confirmation tokens <a class="header-anchor" href="#confirmation-tokens" aria-label="Permalink to “Confirmation tokens”">​</a></h2><p>Deleting a recipe, organizer, cookbook, shopping list or comment, merging foods or units, and creating a public share link all require a server-generated token: the first call returns the token together with a description of what is about to happen, the second call — same tool, same arguments, plus the token — performs it.</p><p>The tokens are single-use and bound to the specific target, so a model cannot satisfy the gate on its own and a token issued for one target cannot be replayed against another. For operations on a set of ids the token is bound to a fingerprint of the whole sorted set — a confirmation for three shopping-list items cannot delete a fourth appended between the two calls — and for a merge to the direction as well, because swapping the arguments would destroy the wrong record.</p><p><code>create_share_token</code> is guarded even though it destroys nothing: it is the one tool that widens who can see the data, and unlike a deletion the effect is invisible until someone uses the link. <code>delete_share_token</code> needs no confirmation — it narrows access.</p><p>Confirmation prompts quote <strong>no upstream text</strong> — ids, counts and flags only — so a hostile recipe name cannot ride along into the prompt the user approves.</p><h2 id="untrusted-content" tabindex="-1">Untrusted content <a class="header-anchor" href="#untrusted-content" aria-label="Permalink to “Untrusted content”">​</a></h2><p><strong>Recipes are attacker-controlled text.</strong> A recipe imported from a website carries whatever that site wrote, and it stays in the database afterwards, so the content comes back through <code>get_recipe</code> and <code>search_recipes</code> long after the import. Comments come from other users of the instance. Every tool result that can contain instance content is therefore prefixed with an explicit untrusted-content marker telling the model to treat it as data, not as instructions.</p><p><strong>Mealie performs the fetch, not this server.</strong> <code>import_recipe_from_url</code>, <code>preview_recipe_url</code> and the image import hand a URL or a payload to Mealie, which retrieves it from inside its own network. URLs are therefore restricted to <code>http</code> and <code>https</code> — zod&#39;s <code>.url()</code> alone would accept <code>file:</code>, <code>javascript:</code> and <code>data:</code> — and loopback, private-range, link-local and <code>.lan</code>/<code>.internal</code>/<code>.local</code> hosts are refused, since no recipe lives there. This is not a complete SSRF defence and cannot be: the name is resolved by Mealie, and a public name can point at a private address. The real boundary is Mealie&#39;s own network egress.</p><h2 id="bounded-responses" tabindex="-1">Bounded responses <a class="header-anchor" href="#bounded-responses" aria-label="Permalink to “Bounded responses”">​</a></h2><p>Oversized results drop whole items rather than cutting the JSON mid-string, and a response body is never read past 8 MB. Redirects are refused so the token cannot be resent to another host.</p><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Use <a href="https://github.com/ni-c/mealie-mcp/security/advisories/new" target="_blank" rel="noreferrer">private vulnerability reporting</a>. Do not open a public issue for an unpatched vulnerability, and do not include real credentials, tokens, hostnames or private configuration in a report. You can expect an initial response within a week; fixed vulnerabilities are published as a new release with a note in the changelog. Only the latest release and the current <code>main</code> branch receive security fixes.</p>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};